[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$ManifestPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($ManifestPath)){throw 'ManifestPath must be project-relative.'};$rel=$ManifestPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'ManifestPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Fixture manifest missing: $rel"}
$m=([Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($full))|ConvertFrom-Json);foreach($f in @('schemaVersion','fixtureId','writeRoot','cleanup','rollback','expected')){if([string]::IsNullOrWhiteSpace([string]$m.$f)-and @($m.$f).Count -eq 0){throw "Fixture manifest missing ${f}."}};if([string]$m.schemaVersion -ne '1'){throw 'Fixture schemaVersion must be 1.'};if([string]$m.writeRoot -notmatch '^ES/Output/'){throw 'Fixture writeRoot must remain under ES/Output.'};if([int]$m.maxObjects -lt 1-or [int]$m.maxObjects -gt 10000){throw 'Fixture maxObjects outside bounded range.'}
Write-Output "PASS: fixture manifest is deterministic and cleanable: $rel"
